import { defineStyles } from '@/utils/defineStyles'
import { View } from 'react-native'
import CodeEditor, {
	CodeEditorSyntaxStyles
} from '@rivascva/react-native-code-editor'
import { useTheme } from '@/theme'
import { useStreamingTypingEffect } from '../../hooks/useStreaming'

const GRADIENT_LENGTH = 64

export const CodePreviewBlock = ({ code }: { code: string }) => {
	const { isDark } = useTheme()
	const { displayText } = useStreamingTypingEffect(code, 1)

	return (
		<View style={styles.codePreviewContainer}>
			<CodeEditor
				key={displayText}
				style={{
					fontSize: 12,
					inputLineHeight: 16,
					highlighterLineHeight: 16
				}}
				language="javascript"
				syntaxStyle={
					isDark
						? CodeEditorSyntaxStyles.a11yDark
						: CodeEditorSyntaxStyles.a11yLight
				}
				showLineNumbers
				initialValue={displayText}
				readOnly={true}
				autoFocus={false}
			/>
		</View>
	)
}

const styles = defineStyles({
	codePreviewContainer: {
		alignSelf: 'flex-start',
		paddingLeft: 28
	},
	gradient: {
		position: 'absolute',
		zIndex: 1
	},
	gradientOverlayTop: {
		top: 0,
		left: 28,
		width: '100%',
		height: GRADIENT_LENGTH
	},
	gradientOverlayBottom: {
		bottom: 0,
		left: 28,
		width: '100%',
		height: GRADIENT_LENGTH
	},
	gradientOverlayLeft: {
		left: 28,
		top: 0,
		width: GRADIENT_LENGTH / 2,
		height: '100%'
	},
	gradientOverlayRight: {
		right: 0,
		top: 0,
		width: GRADIENT_LENGTH / 2,
		height: '100%'
	}
})
